   496→public(package) fun handle_liquidation<MarketType, DebtType, CollateralType>(
   497→    self: &mut Market<MarketType>,
   498→    obligation_id: ID,
   499→    available_repay_coin: Coin<DebtType>,
   500→    coin_decimals_registry: &CoinDecimalsRegistry,
   501→    x_oracle: &XOracle,
   502→    clock: &Clock,
   503→    now: u64,
   504→    ctx: &mut TxContext,
   505→): (Coin<CollateralType>, Coin<DebtType>, u64) {
   506→    let MarketConfiguration { close_factor, close_factor_bypass_min_value } = *self.market_config();
   507→
   508→    let obligation = self.obligations.borrow_mut(obligation_id);
   509→    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());
   510→
   511→    let emode_group_id = obligation.emode_group();
   512→    let collateral_name = type_name::with_defining_ids<CollateralType>();
   513→
   514→    let emode_group = self.emode_group_registry.borrow_emode_group_mut(emode_group_id);
   515→    let collateral_setting = emode_group.borrow_emode(collateral_name).collateral();
   516→    // cannot liquidate asset that is not collateral
   517→    assert!(collateral_setting.can_be_collateral(), error::asset_not_collateral());
   518→
   519→    let asset = self.assets.load_mut_by_type(collateral_name);
   520→    assert!(!asset.liquidation_paused(), error::liquidation_paused_for_asset());
   521→
   522→    let liquidation_params = LiquidationParams {
   523→        liquidation_ltv_threshold_override: std::option::none(),
   524→        liquidation_incentive: collateral_setting.liquidation_incentive(),
   525→        liquidation_revenue_factor: self.assets.load_by_type(type_name::with_defining_ids<CollateralType>()).asset_config().liquidation_fee_rate(),
   526→        close_factor,
   527→        close_factor_bypass_min_value,
   528→    };
   529→
   530→    liquidation_inner<MarketType, DebtType, CollateralType>(
   531→        &mut self.id,
   532→        &self.assets,
   533→        emode_group,
   534→        &mut self.reserves,
   535→        obligation,
   536→        &liquidation_params,
   537→        available_repay_coin,
   538→        coin_decimals_registry,
   539→        x_oracle,
   540→        clock,
   541→        now,
   542→        ctx,
   543→    )
   544→}
