   858→fun refresh_obligation_assets_interest<MarketType>(
   859→    assets: &GenericCoinTypeStorage<Asset<MarketType>>,
   860→    emode_group: &EModeGroup,
   861→    reserves: &mut GenericCoinTypeStorage<Reserve<MarketType>>,
   862→    obligation: &mut Obligation<MarketType>,
   863→    now: u64,
   864→) {
   865→    refresh_obligation_borrow_interest<MarketType>(assets, reserves, obligation, now);
   866→
   867→    // collateral
   868→    let asset_types = obligation.deposit_types();
   869→
   870→    let (mut i, n) = (0, asset_types.length());
   871→
   872→    while (i < n) {
   873→        let name = asset_types[i];
   874→
   875→        let asset = assets.load_by_type(name);
   876→        let collateral_settings = emode_group.borrow_emode(name).collateral();
   877→
   878→        // update index first, since it's not used after this point
   879→        i = i + 1;
   880→
   881→        // cannot be collateral, ignore
   882→        if (!collateral_settings.can_be_collateral()) { continue };
   883→
   884→        accrue_interest<MarketType>(name, reserves, asset.asset_config(), asset.interest_model(), now);
   885→    };
   886→}
